// Regenerates src/components/quire/vault-corpus.generated.ts from a real
// Obsidian vault, so the live-preview sweep test runs against actual notes.
//   node scripts/make-vault-corpus.mjs [vault-dir]
// The generated file is gitignored — it contains personal note content.
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const VAULT = process.argv[2] ?? `${process.env.HOME}/Desktop/obsidian-vault`;
const OUT = new URL("../src/components/quire/vault-corpus.generated.ts", import.meta.url);
const SKIP_DIRS = new Set([".obsidian", ".trash", "node_modules", ".git"]);
const MAX_FILES = 120;
const MAX_CHARS = 2500;

const files = [];
const walk = (dir) => {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) {
      if (!SKIP_DIRS.has(entry)) walk(full);
    } else if (entry.endsWith(".md") && st.size < 200_000) {
      files.push(full);
    }
  }
};
walk(VAULT);
files.sort();

// Evenly spread the sample over the sorted list, so folders are represented.
const step = Math.max(1, Math.ceil(files.length / MAX_FILES));
const picked = files.filter((_, i) => i % step === 0).slice(0, MAX_FILES);

const entries = picked.map((full) => {
  let content = readFileSync(full, "utf8");
  if (content.length > MAX_CHARS) {
    const cut = content.slice(0, MAX_CHARS);
    content = cut.slice(0, cut.lastIndexOf("\n") + 1);
  }
  const name = full.slice(VAULT.length + 1);
  return `  ${JSON.stringify({ name, content })}`;
});

writeFileSync(
  OUT,
  `// AUTO-GENERATED by scripts/make-vault-corpus.mjs — do not edit.\n` +
    `// Sampled from ${JSON.stringify(VAULT)}: ${entries.length} of ${files.length} files.\n` +
    `export const corpus = [\n${entries.join(",\n")},\n] as const;\n`,
);
console.log(`wrote ${entries.length} files (of ${files.length}) to ${OUT.pathname}`);
